std::uintptr_t SF_VTable_Lookup(const char* name)
{
	for (const IdentifiedVTable& known : g_identified)
	{
		if (std::strcmp(known.Name, name) == 0)
		{
			// The identifier is tested first, because CommonLib ends the process for one the library does not contain.
			// CommonLib still states an identifier for a class a game update removed, which the later libraries do not contain. On VR the entry states an offset, and id() is 0.
			const std::uint64_t id = known.Id.id();
			return id == 0 || REL::IDDB::get().names(id) ? known.Id.address() : 0;
		}
	}
	for (const OffsetVTable& known : g_offsets)
	{
		if (std::strcmp(known.Name, name) == 0)
		{
			return known.Offset.address();
		}
	}
	return 0;
}
